;const _e7287=WF.el("tr",{});const _e7288=WF.el("th",{scope:"col"},"Value");_e7287.appendChild(_e7288);const _e7289=WF.el("th",{scope:"col"},"Output");_e7287.appendChild(_e7289);_e7286.appendChild(_e7287);_e7285.appendChild(_e7286);const _e7290=WF.el("tbody",{});const _e7291=WF.el("tr",{});const _e7292=WF.el("td",{});const _e7293=WF.el("div",{className:"wf-markdown",markdown:"`human`"});_e7292.appendChild(_e7293);_e7291.appendChild(_e7292);const _e7294=WF.el("td",{},"Rendered findings on standard error.");_e7291.appendChild(_e7294);_e7290.appendChild(_e7291);const _e7295=WF.el("tr",{});const _e7296=WF.el("td",{});const _e7297=WF.el("div",{className:"wf-markdown",markdown:"`json`"});_e7296.appendChild(_e7297);_e7295.appendChild(_e7296);const _e7298=WF.el("td",{},"One document on standard output: every finding with its code, place, hint, related places and fixes, and the counts.");_e7295.appendChild(_e7298);_e7290.appendChild(_e7295);const _e7299=WF.el("tr",{});const _e7300=WF.el("td",{});const _e7301=WF.el("div",{className:"wf-markdown",markdown:"`sarif`"});_e7300.appendChild(_e7301);_e7299.appendChild(_e7300);const _e7302=WF.el("td",{},"SARIF 2.1.0, for GitHub code scanning and every other SARIF reader.");_e7299.appendChild(_e7302);_e7290.appendChild(_e7299);const _e7303=WF.el("tr",{});const _e7304=WF.el("td",{});const _e7305=WF.el("div",{className:"wf-markdown",markdown:"`github`"});_e7304.appendChild(_e7305);_e7303.appendChild(_e7304);const _e7306=WF.el("td",{});const _e7307=WF.el("div",{className:"wf-markdown",markdown:"`::error file=…` annotations on standard output, which a workflow shows on the pull request; the rendered findings stay on standard error."});_e7306.appendChild(_e7307);_e7303.appendChild(_e7306);_e7290.appendChild(_e7303);_e7285.appendChild(_e7290);_e7067.appendChild(_e7285);const _e7308=WF.el("div",{className:"wf-markdown",markdown:"With `json` or `sarif`, the build's progress goes to standard error, so standard output holds the document alone.\n\n`--cache` keeps what it renders in `.wf-cache/build/`. A page is taken from the cache when its inputs are unchanged: its own text, every component it reaches, and what every page reads — the shell, the stores, constants and data, every page's title and route, the config, the translations and the compiler. The output is byte for byte what a build without `--cache` writes. A build with nothing to reuse fills the cache, and each build keeps only the entries it used.\n\n`--studio` stamps every element's root with `data-wf-node`, its node id, which is the same in the pre-rendered page and the live one. An instance of one of the project's components also carries `data-wf-call`: the calls that made it, innermost first. `nodes.json`, written beside the site, maps each id to where it is written (file, bytes, line), what it calls, its parent, the loops and branches it is inside, and what its arguments read. A build without `--studio` stamps nothing and removes any `nodes.json` it finds.\n\n`--stats` prints every text file with its gzipped size and how much it changed since the last build, the runtime modules the build kept and what reached each one, and the design tokens it left out.\n\nSee also: [Diagnostics](/docs/guide/diagnostics), [Performance](/docs/guide/performance)."});_e7067.appendChild(_e7308);const _e7309=WF.el("h3",{className:"wf-heading",id:"wf-serve"},"wf serve");_e7067.appendChild(_e7309);const _e7310=WF.el("div",{className:"wf-markdown",markdown:"Runs the development server: it builds once, serves the output, and rebuilds and reloads on every save.\n\n**Usage:** `wf serve [OPTIONS]`"});_e7067.appendChild(_e7310);const _e7311=WF.el("table",{className:"wf-table"},WF.el("caption",{className:"wf-visually-hidden"},"wf serve"));const _e7312=WF.el("thead",{});const _e7313=WF.el("tr",{});const _e7314=WF.el("th",{scope:"col"},"Option");_e7313.appendChild(_e7314);const _e7315=WF.el("th",{scope:"col"},"Value");_e7313.appendChild(_e7315);const _e7316=WF.el("th",{scope:"col"},"Default");_e7313.appendChild(_e7316);const _e7317=WF.el("th",{scope:"col"},"Meaning");_e7313.appendChild(_e7317);_e7312.appendChild(_e7313);_e7311.appendChild(_e7312);const _e7318=WF.el("tbody",{});const _e7319=WF.el("tr",{});const _e7320=WF.el("td",{});const _e7321=WF.el("div",{className:"wf-markdown",markdown:"`-d`, `--dir`"});_e7320.appendChild(_e7321);_e7319.appendChild(_e7320);const _e7322=WF.el("td",{},"a directory");_e7319.appendChild(_e7322);const _e7323=WF.el("td",{});const _e7324=WF.el("div",{className:"wf-markdown",markdown:"`.`"});_e7323.appendChild(_e7324);_e7319.appendChild(_e7323);const _e7325=WF.el("td",{},"The project to serve.");_e7319.appendChild(_e7325);_e7318.appendChild(_e7319);const _e7326=WF.el("tr",{});const _e7327=WF.el("td",{});const _e7328=WF.el("div",{className:"wf-markdown",markdown:"`--host`"});_e7327.appendChild(_e7328);_e7326.appendChild(_e7327);const _e7329=WF.el("td",{},"an address");_e7326.appendChild(_e7329);const _e7330=WF.el("td",{});const _e7331=WF.el("div",{className:"wf-markdown",markdown:"`127.0.0.1`"});_e7330.appendChild(_e7331);_e7326.appendChild(_e7330);const _e7332=WF.el("td",{});const _e7333=WF.el("div",{className:"wf-markdown",markdown:"Where to listen: this machine only, unless told otherwise. `0.0.0.0` lets a phone on the same network reach it."});_e7332.appendChild(_e7333);_e7326.appendChild(_e7332);_e7318.appendChild(_e7326);const _e7334=WF.el("tr",{});const _e7335=WF.el("td",{});const _e7336=WF.el("div",{className:"wf-markdown",markdown:"`--allow-output-outside`"});_e7335.appendChild(_e7336);_e7334.appendChild(_e7335);const _e7337=WF.el("td",{},"—");_e7334.appendChild(_e7337);const _e7338=WF.el("td",{},"off");_e7334.appendChild(_e7338);const _e7339=WF.el("td",{});const _e7340=WF.el("div",{className:"wf-markdown",markdown:"Lets `build.output` name a directory outside the project."});_e7339.appendChild(_e7340);_e7334.appendChild(_e7339);_e7318.appendChild(_e7334);_e7311.appendChild(_e7318);_e7067.appendChild(_e7311);const _e7341=Component_Terminal({lines:[({command:"wf serve",output:""}),({command:"wf serve --host 0.0.0.0     # a phone on this network, at the address it prints",output:""})]});_e7067.appendChild(_e7341);const _e7342=WF.el("div",{className:"wf-markdown",markdown:"The server listens on `dev.port` (3000), on `127.0.0.1`: nothing else on the network can reach it unless `--host` says so. It watches `src/`, `public/` and the config, rebuilds on a change, and reloads every open tab. Each rebuild is a `wf build --cache`, so only the pages the change reached are rendered again.\n\nIt serves the build and nothing beside it: an address that climbs out (`/../`, written plainly or as `%2e%2e`), holds a backslash or a NUL, or reaches a link out of the build is a `404`. It answers only a request whose `Host` is a name it is reached by — `localhost`, an address written as numbers, the `--host` it was given, and with `--host 0.0.0.0` a `.local` name — so a page on another site cannot point a name of its own at this machine and read the build (DNS rebinding); any other gets a `421`. It answers several requests at once, streams files rather than reading them whole, and compresses a file once until it changes.\n\nWhen a build fails, the last good page stays up and the error is drawn over it — file, line, message and hint — until a save fixes it. The overlay is served at `/__wf/dev.js`, and the build's state, as JSON, at `/__wf/status`.\n\nEvery page the server sends also carries a **stores** button. It shows what each store holds, a log of every action with the state on each side of it, and lets you put a store back to before an action ran ([Stores](/docs/guide/stores#looking-at-one-while-it-runs)). The service worker of an offline site is removed under `wf serve`, so an edit is never hidden behind its cache.\n\nA request that is not a navigation — a `fetch`, a script, an image — for a file the build did not write gets a `404`, as a host would send, and a line in the terminal naming the file. Only a navigation gets the single-page shell. (Answering a missing API with the shell's HTML makes the page fail to parse it, far from the cause.)\n\nA build under `wf serve` is a *development build*, and it adds these checks to the running page:\n\n- A response with a declared type — `resource users: [User] = …`, an `api` endpoint's `-> User` — is held to that type as it arrives. One that does not match takes the `error` arm as a `.parse` error naming the place: `$[1].name is missing`.\n- A route no page answers (and no `path: \"*\"` page catches) shows a `404` box saying so. A deployed page shows nothing.\n- An item of a `for` that throws shows where it is and what it threw, and the rest of the list draws. On a deployed page the item leaves a gap and the console says why.\n- An effect that changes what it reads every time it runs is stopped after a hundred runs, with a warning, instead of overflowing the stack. A deployed page stops it too, silently.\n\nSee also: [`dev` in Configuration](/docs/guide/config#dev)."});_e7067.appendChild(_e7342);const _e7343=WF.el("h3",{className:"wf-heading",id:"wf-generate"},"wf generate");_e7067.appendChild(_e7343);const _e7344=WF.el("div",{className:"wf-markdown",markdown:"Writes a starter page, component or store.\n\n**Usage:** `wf generate [OPTIONS] KIND NAME`"});_e7067.appendChild(_e7344);const _e7345=WF.el("table",{className:"wf-table"},WF.el("caption",{className:"wf-visually-hidden"},"wf generate"));const _e7346=WF.el("thead",{});const _e7347=WF.el("tr",{});const _e7348=WF.el("th",{scope:"col"},"Option");_e7347.appendChild(_e7348);const _e7349=WF.el("th",{scope:"col"},"Value");_e7347.appendChild(_e7349);const _e7350=WF.el("th",{scope:"col"},"Default");_e7347.appendChild(_e7350);const _e7351=WF.el("th",{scope:"col"},"Meaning");_e7347.appendChild(_e7351);_e7346.appendChild(_e7347);_e7345.appendChild(_e7346);const _e7352=WF.el("tbody",{});const _e7353=WF.el("tr",{});const _e7354=WF.el("td",{});const _e7355